// Regenerate src/changelog-source.ts from the checked-in root CHANGELOG.md.
// Run after editing CHANGELOG.md: node scripts/embed-changelog.mjs
//
// The generated file becomes ordinary TypeScript source, so it ships with
// the rest of src/** in the deployed function bundle without depending on
// any Vercel includeFiles configuration or a runtime filesystem read of a
// file outside src/.
//
// It also keeps the permanent id ledger for GET /api/changelog: the previous
// ledger is read back out of the generated file, reconciled against the new
// CHANGELOG.md by scripts/changelog-ids.mjs, and written out again, so an
// entry's id survives edits and redating and a dropped id is never reused.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { assignChangelogIds } from './changelog-ids.mjs'

const SOURCE_PATH = 'src/changelog-source.ts'
const LEDGER_BEGIN = '// changelog-ledger:begin'
const LEDGER_END = '// changelog-ledger:end'

const escapeTemplate = value => value
  .replace(/\\/g, '\\\\')
  .replace(/`/g, '\\`')
  .replace(/\$\{/g, '\\${')

function fail(message) {
  console.error(message)
  process.exit(1)
}

function readPreviousLedger() {
  if (!existsSync(SOURCE_PATH)) return { ledger: [], lastId: 0 }
  const source = readFileSync(SOURCE_PATH, 'utf8')
  const begin = source.lastIndexOf(LEDGER_BEGIN)
  if (begin === -1) return { ledger: [], lastId: 0 }
  const end = source.indexOf(LEDGER_END, begin)
  if (end === -1) fail(`${SOURCE_PATH} has a ledger start marker but no end marker; restore it from git before regenerating`)
  const block = source.slice(begin + LEDGER_BEGIN.length, end)
  const lastIdMatch = /export const CHANGELOG_LAST_ID = (\d+)/u.exec(block)
  if (!lastIdMatch) fail(`${SOURCE_PATH} ledger block has no CHANGELOG_LAST_ID; restore it from git before regenerating`)
  const ledger = block.split(/\r?\n/u)
    .map(line => /^\s*(\{.*\}),?\s*$/u.exec(line)?.[1])
    .filter(row => row !== undefined)
    .map(row => JSON.parse(row))
  return { ledger, lastId: Number(lastIdMatch[1]) }
}

const changelog = readFileSync('CHANGELOG.md', 'utf8')
const previous = readPreviousLedger()
const { ledger, lastId } = assignChangelogIds(previous.ledger, previous.lastId, changelog)
const ledgerRows = ledger.map(row => `  ${JSON.stringify(row)},`).join('\n')

writeFileSync(
  SOURCE_PATH,
  `// GENERATED by scripts/embed-changelog.mjs — edit CHANGELOG.md instead.
export const CHANGELOG_MARKDOWN = \`${escapeTemplate(changelog)}\`

export interface ChangelogLedgerRow {
  readonly id: number
  readonly date: string
  readonly category: string
  readonly sha256: string
}

// Permanent entry ids for GET /api/changelog: one row per bullet, in file
// order. Assigned by scripts/changelog-ids.mjs; never edit by hand.
${LEDGER_BEGIN}
export const CHANGELOG_LAST_ID = ${lastId}
export const CHANGELOG_ENTRY_LEDGER: readonly ChangelogLedgerRow[] = [
${ledgerRows}
]
${LEDGER_END}
`,
)
console.log(`${SOURCE_PATH} regenerated (${ledger.length} entries, last id ${lastId})`)
